mapper.select:
SELECT h_waring.w_id, h_waring.alarm_type_name, h_waring.alarm_level_name, h_waring.device_name, h_waring.picture_absolute_url, h_waring.org_name, h_waring.team, h_waring.device_id, h_waring.alarm_time, h_waring.is_handle, h_waring.ip FROM h_handle INNER JOIN h_waring ON h_waring.w_id = h_handle.w_id
AND h_waring.alarm_type_name like concat('%', #{alarm_type_name}, '%')
AND h_waring.alarm_level_name like concat('%', #{alarm_level_name}, '%')
AND h_waring.device_name like concat('%', #{device_name}, '%')
AND h_waring.org_name like concat('%', #{org_name}, '%')
AND UNIX_TIMESTAMP(h_waring.alarm_time) >= #{begin}
AND UNIX_TIMESTAMP(h_waring.alarm_time) <= #{end}
AND h_waring.team = #{team}
AND h_handle.h_remark = "测试"
ORDER BY alarm_time DESC
